public String cipher(int n, int k, String encoded) {
    int[] s = new int[n];
    s[0] = encoded.charAt(0) - '0';
    for (int i = 1; i < n; i++) {
        int window = 0;
        for (int j = Math.max(0, i - k + 1); j <= i - 1; j++) {
            window ^= s[j];                  // XOR of previously decoded bits
        }
        s[i] = (encoded.charAt(i) - '0') ^ window;
    }
    StringBuilder sb = new StringBuilder();
    for (int b : s) sb.append(b);
    return sb.toString();
}

