public String cipher(int n, int k, String encoded) {
    char[] s = new char[n];
    int prev = encoded.charAt(0) - '0';
    s[0] = (char) ('0' + prev);              // first window is just s[0]
    for (int i = 1; i < n; i++) {
        int cur = encoded.charAt(i) - '0';
        int bit = cur ^ (encoded.charAt(i - 1) - '0');   // enc[i] ^ enc[i-1] = s[i] ^ s[i-k]
        if (i >= k) {
            bit ^= (s[i - k] - '0');         // remove the bit that left the window
        }
        s[i] = (char) ('0' + bit);
    }
    return new String(s);
}

code.python:
def cipher(n: int, k: int, encoded: str) -> str:
    s = [0] * n
    s[0] = int(encoded[0])                    # first window is just s[0]
    for i in range(1, n):
        bit = int(encoded[i]) ^ int(encoded[i - 1])   # = s[i] ^ s[i-k]
        if i >= k:
            bit ^= s[i - k]                   # remove the bit that left the window
        s[i] = bit
    return "".join(map(str, s))
